<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {beijingTime,orderStatus} from '@quote/archive-client';
import type {PcApi} from '../api';
import {BusinessOperations,type BusinessOperation} from '../business-pending';
import {MasterReader,masterForm,masterFields,reviewMaster,tabLabels,kindLabels,adminStorage,assertAdminReceipt,isDenied,HandoffDraft,type AdminKind,type AdminTab,type AdminReview,type FormValues,type InternalAccount,type MasterRecord,type HandoffPreview} from '../../../../packages/master-client/src';
import type {MasterPage,SourceFile,TemporaryCredentialResult} from '../../../../packages/contracts/src';
import SourceFiles from './SourceFiles.vue';
import SourceBatches from './SourceBatches.vue';
import CatalogPanel from './CatalogPanel.vue';
interface Account extends InternalAccount {bindings:{id:string;appId:string}[];}
const props=defineProps<{api:Pick<PcApi,'get'|'post'|'write'>;userId:string;initialTab?:AdminTab;locked?:boolean}>(),emit=defineEmits<{(e:'busy-changed',v:boolean):void;(e:'failure',v:unknown):void}>();
const tab=ref<AdminTab>(props.initialTab&&props.initialTab in tabLabels?props.initialTab:'accounts'),busy=ref(false),childBusy=ref(false),storageError=ref(''),error=ref(''),notice=ref(''),users=ref<Account[]>([]),userKeyword=ref(''),userPage=ref(1),query=reactive({keyword:'',includeInactive:true}),reader=reactive(new MasterReader(path=>props.api.get(path))),form=ref<FormValues|null>(null),review=ref<AdminReview|null>(null),ack=ref(false),reset=ref<{user:Account;action:'password'|'binding';bindingId:string}|null>(null),resetReason=ref(''),recoveryNotFound=ref(false),recovering=ref(false),sourcePanel=ref<InstanceType<typeof SourceBatches>|null>(null),catalogPanel=ref<InstanceType<typeof CatalogPanel>|null>(null),logoRef=ref<InstanceType<typeof SourceFiles>|null>(null),lookupKeyword=ref(''),lookups=reactive<{hospitals:MasterRecord[];items:MasterRecord[]}>({hospitals:[],items:[]}),handoff=reactive(new HandoffDraft()),handoffReady=ref(false),handoffAck=ref(false),handoffOrderPage=ref(1),handoffHospitalPage=ref(1),credential=ref<{loginName:string;password:string;expiresAt:string}|null>(null);let disposed=false;
const kind=computed(()=>tab.value in kindLabels?tab.value as AdminKind:null),fields=computed(()=>kind.value?masterFields(kind.value):[]),dirty=computed(()=>!!form.value||!!reset.value||tab.value==='handoff'&&!!(handoff.fromId||handoff.toId||handoff.reason||handoff.preview)),ownLocked=computed(()=>!!props.locked||busy.value||recovering.value),locked=computed(()=>ownLocked.value||childBusy.value),writeLocked=computed(()=>locked.value||!!operations?.pending||!!storageError.value||!!review.value||!!credential.value),navigationLocked=computed(()=>locked.value||dirty.value||!!review.value||!!operations?.pending||!!credential.value),sales=computed(()=>users.value.filter(u=>u.active&&u.role==='salesperson')),filteredUsers=computed(()=>users.value.filter(u=>(u.name+' '+u.loginName+' '+u.phone).toLowerCase().includes(userKeyword.value.toLowerCase()))),visibleUsers=computed(()=>filteredUsers.value.slice((userPage.value-1)*25,userPage.value*25)),rows=computed(()=>(reader.page?.items||[]) as (MasterRecord&Record<string,any>)[]),pages=computed(()=>reader.page?Math.max(1,Math.ceil(reader.page.total/reader.page.pageSize)):1),logoFiles=computed(()=>logoRef.value?.sourceFiles||[]),hasPending=computed(()=>!!operations?.pending);
let operations:Pick<BusinessOperations,'pending'|'mutate'|'check'|'retry'>|null=null,lastRecoveryResult:unknown;
try{operations=reactive(new BusinessOperations(props.userId,async<T>(path:string)=>{const r=await props.api.get<T>(path);if(path.startsWith('/operations/')&&(r as any)?.status==='committed'&&operations?.pending){assertAdminReceipt(operations.pending,(r as any).result);lastRecoveryResult=(r as any).result;}return r;},async<T>(path:string,method:'POST'|'PUT'|'PATCH',body:unknown,key:string)=>{const r=await props.api.write<T>(path,method,body,key);assertAdminReceipt(operations?.pending||{path,body:body as Record<string,unknown>},r);if(recovering.value)lastRecoveryResult=r;return r;},adminStorage(localStorage)));}catch(e){storageError.value=(e as Error).message;}
watch(()=>busy.value||recovering.value||childBusy.value||dirty.value||!!review.value||!!operations?.pending||!!credential.value,v=>emit('busy-changed',v),{immediate:true,flush:'sync'});
watch(()=>review.value,()=>{ack.value=false;});
function clearPrivate(){users.value=[];reader.page=null;lookups.hospitals=[];lookups.items=[];form.value=null;review.value=null;reset.value=null;credential.value=null;handoff.resetPreview();handoff.fromId='';handoff.toId='';handoff.reason='';handoffReady.value=false;}
function report(e:unknown){error.value=e instanceof Error?e.message:'资料操作失败，请重试。';if(isDenied(e))clearPrivate();if((e as any)?.code==='VERSION_CONFLICT'){handoff.rejectPreview(e);review.value=null;handoffReady.value=false;error.value+=' 请放弃本次未提交修改，载入最新资料后重新复核。';}if(String((e as any)?.code||'').includes('PREVIEW')){handoff.rejectPreview(e);handoffReady.value=false;error.value+=' 请按当前范围重新预览。';}emit('failure',e);}
async function run(action:()=>Promise<void>){if(busy.value||disposed)return;busy.value=true;error.value='';notice.value='';try{await action();}catch(e){if(!disposed)report(e);}finally{if(!disposed)busy.value=false;}}
async function loadUsers(){const r=await props.api.get<{items:Account[]}>('/admin/users');if(!Array.isArray(r?.items))throw new Error('内部账号列表无法核实。');users.value=r.items;userPage.value=Math.min(userPage.value,Math.max(1,Math.ceil(filteredUsers.value.length/25)));}
async function loadLookup(){const target=kind.value==='purchasers'?'hospitals':kind.value==='variants'?'items':null;if(!target)return;const r=await props.api.get<MasterPage>('/admin/master-data/'+target+'?keyword='+encodeURIComponent(lookupKeyword.value)+'&includeInactive=true&page=1&pageSize=100');lookups[target]=r.items;}
async function loadCurrent(page=reader.page?.page||1){if(tab.value==='accounts'||tab.value==='handoff'){await loadUsers();return;}if(kind.value){await reader.load(kind.value as Exclude<AdminKind,'accounts'>,{...query,page,pageSize:25});if(kind.value==='hospitals')await loadUsers();if(kind.value==='purchasers')await loadLookup();return;}}
async function refresh(){if(navigationLocked.value)return;if(tab.value==='source-batches')return sourcePanel.value?.refresh();if(tab.value==='catalog')return catalogPanel.value?.refresh();await run(()=>loadCurrent());}
async function switchTab(next:AdminTab){if(navigationLocked.value)return;tab.value=next;query.keyword='';lookupKeyword.value='';reader.page=null;error.value='';notice.value='';await run(()=>loadCurrent(1));}
async function edit(record?:any){if(writeLocked.value||!kind.value)return;await run(async()=>{lookupKeyword.value='';await loadLookup();form.value=masterForm(kind.value!,record);});}
function discard(){if(locked.value||operations?.pending||logoRef.value?.canLeave()===false)return;form.value=null;review.value=null;reset.value=null;resetReason.value='';handoff.resetPreview();handoff.fromId='';handoff.toId='';handoff.reason='';handoffReady.value=false;handoffAck.value=false;error.value='';}
function hospitalName(id:unknown){return (lookups.hospitals as any[]).find(h=>h.id===id)?.name||'原医院归属';}
function labelValue(key:string,value:unknown){if(key==='salesUserId')return users.value.find(u=>u.id===value)?.name||'所选销售';if(key==='hospitalId')return (lookups.hospitals as any[]).find(h=>h.id===value)?.name||'所选医院';if(key==='itemId')return (lookups.items as any[]).find(i=>i.id===value)?.name||'所选标准商品';if(key==='role')return value==='admin'?'管理员（仅 PC）':'销售员';if(key==='logoFileId')return logoFiles.value.find(f=>f.id===value)?.fileName||'已保存的模板图片';return String(value??'未填写');}
function submitMasterForm(event:SubmitEvent){if((event.submitter as HTMLElement|null)?.closest('.source-files'))return;prepareReview();}
function prepareReview(){if(writeLocked.value||!kind.value||!form.value)return;try{review.value=reviewMaster(kind.value,form.value,props.userId);review.value.details=review.value.details.map((d,i)=>{const f=fields.value.filter(f=>!(kind.value==='accounts'&&form.value?.id&&f.key==='loginName'))[i];return f&&['sales','hospital','item','role','logo'].includes(f.type||'')?{...d,value:labelValue(f.key,review.value!.body[f.key])}:d;});error.value='';}catch(e){error.value=(e as Error).message;}}
async function submit<T>(label:string,path:string,body:Record<string,unknown>,metadata?:Record<string,unknown>):Promise<T>{if(!operations||storageError.value)throw new Error(storageError.value||'本机待核对记录不可用，暂不能提交。');return operations.mutate<T>(label,path,'POST',body,metadata);}
function showCredential(r:unknown){const result=r as TemporaryCredentialResult;if(!result?.credentialGenerated)return;if(result.temporaryPassword){credential.value={loginName:result.user.loginName,password:result.temporaryPassword,expiresAt:result.temporaryPasswordExpiresAt};}else notice.value='原凭证操作已确认，但临时密码仅首次成功时展示，现已无法恢复。若未安全交付，请在核对账号后明确重置密码；系统不会自动重新生成。';}
async function commit(){if(locked.value||operations?.pending||storageError.value||!review.value||!ack.value)return;const current=review.value;await run(async()=>{const result=await submit(current.label,current.path,current.body);form.value=null;review.value=null;reset.value=null;resetReason.value='';showCredential(result);if(!(result as any)?.credentialGenerated)notice.value='资料已保存，列表已重新读取。';await loadCurrent();});}
function startReset(user:Account,action:'password'|'binding',bindingId=''){if(writeLocked.value||user.id===props.userId)return;reset.value={user,action,bindingId};resetReason.value='';}
function reviewReset(){if(writeLocked.value||!reset.value)return;const reason=resetReason.value.trim();if(!reason||reason.length>500){error.value='请填写 1–500 字重置原因。';return;}const r=reset.value;review.value={label:r.action==='password'?'重置内部账号密码':'重置微信绑定',path:'/admin/users/'+r.user.id+(r.action==='password'?'/reset-password':'/reset-binding'),body:{expectedVersion:r.user.version,reason,...r.action==='binding'?{expectedBindingId:r.bindingId}:{}},details:[{label:'账号',value:r.user.name+'（'+r.user.loginName+'）'},{label:'原因',value:reason},...r.action==='binding'?[{label:'待解绑应用',value:r.user.bindings.find(b=>b.id===r.bindingId)?.appId||'原绑定'}]:[]],notice:r.action==='password'?'立即撤销旧会话和旧密码设置票据。新的临时凭证仅本次成功响应展示一次，24 小时有效；本人需设置新密码后重新登录。':'立即撤销该账号旧会话及旧设置票据。仅移除明确选择的微信绑定，不转移旧单或微信订阅授权。'};}
async function copyCredential(){if(!credential.value)return;try{await navigator.clipboard.writeText(credential.value.password);notice.value='已复制临时凭证，请通过安全渠道交付本人。';}catch{notice.value='未能自动复制。可手工选中下方临时凭证复制。';}}
async function recover(retry=false){if(locked.value||!operations?.pending)return;recovering.value=true;error.value='';lastRecoveryResult=undefined;try{const status=retry?(await operations.retry(),'committed'):await operations.check();recoveryNotFound.value=status==='not_found';if(status==='committed'){form.value=null;review.value=null;reset.value=null;handoff.resetPreview();handoff.fromId='';handoff.toId='';handoff.reason='';handoffReady.value=false;showCredential(lastRecoveryResult);const wasCredential=!!(lastRecoveryResult as any)?.credentialGenerated;lastRecoveryResult=undefined;if(!wasCredential)notice.value='原操作已核实完成，请查阅服务器最新资料。';if(tab.value==='source-batches')await sourcePanel.value?.afterRecovery();else await loadCurrent(1);}}catch(e){report(e);}finally{recovering.value=false;}}
function handoffChanged(resetAll=true){handoffReady.value=false;handoffAck.value=false;if(resetAll)handoff.resetPreview();}
async function previewHandoff(empty=false){if(writeLocked.value)return;handoffReady.value=false;handoffAck.value=false;await run(async()=>{const scope=handoff.scope(empty),result=await props.api.post<HandoffPreview>('/admin/sales-handoffs/preview',scope);handoff.acceptPreview(result,scope);handoffOrderPage.value=1;handoffHospitalPage.value=1;if(!empty){handoff.executionBody();handoffReady.value=true;notice.value='最终范围已复核；预览 15 分钟有效。执行时仍会检查双方身份、版本及全部待办。';}});}
function selectAllHandoff(){if(writeLocked.value)return;try{handoff.selectAll();handoffReady.value=false;handoffAck.value=false;}catch(e){error.value=(e as Error).message;}}
function selectHandoff(kind:'orders'|'hospitals',id:string,checked:boolean){if(writeLocked.value)return;handoff[kind]=handoff[kind].filter(v=>v!==id);if(checked)handoff[kind].push(id);handoffReady.value=false;handoffAck.value=false;}
async function executeHandoff(){if(locked.value||operations?.pending||storageError.value||!handoffReady.value||!handoffAck.value)return;await run(async()=>{const body=handoff.executionBody();await submit('销售离职专项交接并停用原账号','/admin/sales-handoffs',body,handoff.executionMetadata());handoff.resetPreview();handoff.fromId='';handoff.toId='';handoff.reason='';handoffReady.value=false;handoffAck.value=false;notice.value='责任交接已完成，原销售账号已停用。原始署名、报价、金额、日期、账期与回款保持保留。';await loadUsers();});}
function beforeLeave(e:BeforeUnloadEvent){if(!canLeave()){e.preventDefault();e.returnValue='';}}
function canLeave(){return !locked.value&&!dirty.value&&!review.value&&!operations?.pending&&!credential.value&&(sourcePanel.value?.canLeave()??true)&&(catalogPanel.value?.canLeave()??true);}
defineExpose({refresh,canLeave});
onMounted(()=>{window.addEventListener('beforeunload',beforeLeave);void run(()=>loadCurrent(1));});onBeforeUnmount(()=>{disposed=true;credential.value=null;lastRecoveryResult=undefined;window.removeEventListener('beforeunload',beforeLeave);emit('busy-changed',false);});
</script>
<template>
 <section class="admin-workspace"><div class="heading"><div><p class="eyebrow">系统管理</p><h1>基础资料与账号</h1><p class="muted">管理员在 PC 维护资料；业务订单、金额与回款继续由当前负责销售处理。</p></div><span class="scope">管理员 · PC</span></div>
 <p v-if="storageError" class="error" role="alert">本机待核对记录不可用：{{storageError}}。提交已暂停，请保留本机资料并联系维护人员。</p>
 <section v-if="operations?.pending" class="recovery" role="status"><strong>「{{operations.pending.label}}」结果待核对</strong><p>原请求和操作标识已保留。请先核对结果，再处理其他资料；重新提交沿用同一操作标识与原始输入。</p><div class="button-row"><button :disabled="locked" @click="recover()">核对原操作结果</button><button v-if="recoveryNotFound" :disabled="locked" @click="recover(true)">按原请求重新提交</button></div><p v-if="recoveryNotFound">暂未找到提交结果。预览凭证若过期且服务端明确拒绝，须按当前事实重新预览。</p></section>
 <section v-if="credential" class="credential-panel" role="status"><h2>临时凭证仅本次展示</h2><p>登录名：<strong>{{credential.loginName}}</strong> · 有效至 {{beijingTime(credential.expiresAt)}}</p><p>请安全交付本人，并由本人设置新密码。关闭或重新加载后不能找回此凭证；遗失后须明确重置。</p><code class="temporary-credential">{{credential.password}}</code><div class="button-row"><button @click="copyCredential">复制临时凭证</button><button @click="credential=null;notice='临时凭证已从页面清除。'">已安全交付，清除本次显示</button></div></section>
 <nav class="admin-tabs" aria-label="管理员资料"><button v-for="(label,key) in tabLabels" :key="key" :class="{selected:tab===key}" :disabled="navigationLocked" @click="switchTab(key)">{{label}}</button></nav>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="filter-note" role="status">{{notice}}</p><p v-if="busy||recovering" role="status">正在读取或提交，请稍候…</p>
 <div v-if="dirty||review" class="unsaved"><span>有未提交资料，请复核提交或明确放弃后再切换。</span><button :disabled="locked||hasPending" @click="discard">放弃本次未提交修改</button></div>
 <template v-if="kind"><div class="result-head"><strong>{{kindLabels[kind]}}</strong><div class="admin-actions"><button :disabled="navigationLocked" @click="refresh">载入最新资料</button><button class="primary" :disabled="writeLocked||!!form||!!reset" @click="edit()">新增{{kindLabels[kind]}}</button></div></div>
 <p v-if="kind==='hospitals'" class="filter-note">医院新单归属变更仅影响未来新单，旧单负责人保留；账期由负责销售在账期页面维护。</p><p v-if="kind==='variants'" class="filter-note">商品规格单位固定 kg。商品库不保存本次最低价、基准价或推荐价。</p>
 <template v-if="kind==='accounts'"><label class="account-search">查找内部账号<input v-model="userKeyword" maxlength="100" :disabled="navigationLocked" @input="userPage=1" placeholder="姓名、登录名或手机号"/></label><div class="table-scroll"><table><thead><tr><th>姓名 / 登录名</th><th>手机号</th><th>身份 / 状态</th><th>密码设置</th><th>微信绑定</th><th>操作</th></tr></thead><tbody><tr v-for="u in visibleUsers" :key="u.id"><td><strong>{{u.name}}</strong><small>{{u.loginName}}{{u.id===userId?' · 本人':''}}</small></td><td>{{u.phone||'未填写'}}</td><td>{{u.role==='admin'?'管理员（仅 PC）':'销售员'}}<small>{{u.active?'启用':'停用'}}</small></td><td>{{u.passwordSetupRequired?'本人待设置密码':'已设置'}}</td><td><span v-if="!u.bindings.length">未绑定</span><small v-for="b in u.bindings" :key="b.id">{{b.appId}} <button :disabled="writeLocked||u.id===userId||!!form||!!reset" @click="startReset(u,'binding',b.id)">重置此绑定</button></small></td><td class="row-actions"><button :disabled="writeLocked||!!form||!!reset" @click="edit(u)">编辑资料</button><button :disabled="writeLocked||u.id===userId||!!form||!!reset" @click="startReset(u,'password')">重置密码</button></td></tr><tr v-if="!visibleUsers.length"><td colspan="6" class="empty">暂无匹配内部账号。</td></tr></tbody></table></div><div class="pagination"><span>共 {{filteredUsers.length}} 个 · 第 {{userPage}} / {{Math.max(1,Math.ceil(filteredUsers.length/25))}} 页</span><button :disabled="navigationLocked||userPage<=1" @click="userPage--">上一页</button><button :disabled="navigationLocked||userPage*25>=filteredUsers.length" @click="userPage++">下一页</button></div></template>
 <template v-else><form class="master-filter" @submit.prevent="run(()=>loadCurrent(1))"><label>关键词<input v-model="query.keyword" maxlength="100" :disabled="navigationLocked"/></label><label class="inline-check"><input v-model="query.includeInactive" type="checkbox" :disabled="navigationLocked"/>包含已停用资料</label><button class="primary" :disabled="navigationLocked">查询</button></form><div class="table-scroll"><table><thead><tr><th>{{kind==='variants'?'标准商品 / 规格':'名称'}}</th><th>资料详情</th><th>状态 / 版本</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td><strong>{{r.name||'商品规格'}}</strong><small v-if="kind==='variants'">{{r.specification||'常用规格'}}</small><small v-if="kind==='items'">{{r.aliases?.join('、')||'无别名'}}</small></td><td><template v-if="kind==='hospitals'">新单负责销售：{{users.find(u=>u.id===r.salesUserId)?.name||'原负责人记录'}}</template><template v-else-if="kind==='purchasers'">{{r.phone}}<small>所属医院：{{hospitalName(r.hospitalId)}} · 不可覆盖</small></template><template v-else-if="kind==='manufacturers'">{{r.contactName||'未填联系人'}}<small>{{r.contactPhone||'未填联系电话'}}</small></template><template v-else-if="kind==='items'">分类：{{r.category||'未分类'}}</template><template v-else-if="kind==='variants'">{{r.origin||'未填产地'}} / {{r.grade||'未填等级'}}<small>{{r.packageDescription||'未填包装'}} · kg</small></template><template v-else>{{r.sellerName}}<small>{{r.contactPhone||'未填电话'}} · {{r.isDefault?'默认报价模板':'备用模板'}}</small></template></td><td>{{r.active?'启用':'停用'}}<small>版本 {{r.version}}</small></td><td><button :disabled="writeLocked||!!form||!!reset" @click="edit(r)">编辑 / 启停 →</button></td></tr><tr v-if="!rows.length&&!busy"><td colspan="4" class="empty">暂无匹配资料。</td></tr></tbody></table></div><div v-if="reader.page" class="pagination"><span>共 {{reader.page.total}} 条 · 第 {{reader.page.page}} / {{pages}} 页</span><button :disabled="navigationLocked||reader.page.page<=1" @click="run(()=>loadCurrent(reader.page!.page-1))">上一页</button><button :disabled="navigationLocked||reader.page.page>=pages" @click="run(()=>loadCurrent(reader.page!.page+1))">下一页</button></div></template>
 <section v-if="form" class="master-editor"><h2>{{form.id?'编辑':'新增'}}{{kindLabels[kind]}}{{form.id?' · 按已读版本 '+form.expectedVersion+' 保存':''}}</h2><form @submit.prevent="submitMasterForm"><div v-if="kind==='purchasers'||kind==='variants'" class="button-row"><label>查找{{kind==='purchasers'?'医院':'标准商品'}}<input v-model="lookupKeyword" maxlength="100" :disabled="writeLocked"/></label><button type="button" :disabled="writeLocked" @click="run(loadLookup)">查找资料（最多 100 条）</button></div><div class="form-grid"><label v-for="field in fields" :key="field.key">{{field.label}}{{field.required?' *':''}}<textarea v-if="field.type==='textarea'" v-model="form[field.key] as string" :maxlength="field.max" :disabled="writeLocked"/><select v-else-if="field.type==='role'" v-model="form[field.key]" :disabled="writeLocked||form.id===userId"><option value="salesperson">销售员</option><option value="admin">管理员（仅 PC）</option></select><select v-else-if="field.type==='sales'" v-model="form[field.key]" :disabled="writeLocked"><option value="">请选择有效销售</option><option v-if="form[field.key]&&!sales.some(s=>s.id===form![field.key])" :value="form[field.key]">原负责人（须选择有效销售）</option><option v-for="s in sales" :key="s.id" :value="s.id">{{s.name}} · {{s.loginName}}</option></select><select v-else-if="field.type==='hospital'||field.type==='item'" v-model="form[field.key]" :disabled="writeLocked||!!form.id&&field.immutable"><option value="">请选择资料</option><option v-if="form[field.key]&&!lookups[field.type==='hospital'?'hospitals':'items'].some(r=>r.id===form![field.key])" :value="form[field.key]">已关联原资料</option><option v-for="r in lookups[field.type==='hospital'?'hospitals':'items']" :key="r.id" :value="r.id">{{(r as any).name}}{{r.active?'':'（已停用）'}}</option></select><select v-else-if="field.type==='logo'" v-model="form[field.key]" :disabled="writeLocked"><option value="">不设置标志图片</option><option v-if="form[field.key]&&!logoFiles.some(f=>f.id===form![field.key])" :value="form[field.key]">保留已关联的标志图片</option><option v-for="f in logoFiles" :key="f.id" :value="f.id">{{f.fileName}}</option></select><input v-else v-model="form[field.key]" :maxlength="field.max" :inputmode="field.type==='phone'?'tel':'text'" :disabled="writeLocked||!!form.id&&field.immutable"/></label><label class="inline-check"><input v-model="form.active" type="checkbox" :disabled="writeLocked||kind==='accounts'&&form.id===userId"/>启用资料</label><label v-if="kind==='templates'" class="inline-check"><input v-model="form.isDefault" type="checkbox" :disabled="writeLocked"/>设为默认报价模板</label></div><p v-if="kind==='purchasers'" class="muted">同一采购员手机号只绑定一家医院。微信绑定由本人通过真实微信登录完成；此处不手填微信身份。</p><p v-if="kind==='accounts'&&form.id===userId" class="muted">本人身份、启停和凭证重置不可从管理员账号维护修改。</p><SourceFiles v-if="kind==='templates'" ref="logoRef" :api="api" :user-id="userId" :reference="{kind:'template'}" :locked="ownLocked||hasPending||!!review" @busy-changed="childBusy=$event" @failure="emit('failure',$event)"/><div class="button-row"><button class="primary" :disabled="writeLocked" type="submit">复核{{form.id?'修改':'新增'}}资料</button><button type="button" :disabled="locked||hasPending" @click="discard">放弃未提交修改</button></div></form></section>
 <section v-if="reset" class="master-editor"><h2>{{reset.action==='password'?'重置密码':'重置微信绑定'}} · {{reset.user.name}}</h2><p class="muted">{{reset.action==='password'?'原会话及旧设置票据立即撤销。临时凭证一次展示，由本人设置新密码。':'只移除所选应用绑定并撤销旧会话，不改变任何订单负责人。'}}</p><form @submit.prevent="reviewReset"><label>重置原因 *<textarea v-model="resetReason" maxlength="500" :disabled="writeLocked"/></label><div class="button-row"><button class="primary" :disabled="writeLocked">复核重置</button><button type="button" :disabled="locked||hasPending" @click="discard">取消本次重置</button></div></form></section>
 </template>
 <template v-else-if="tab==='handoff'"><h2>离职销售专项交接</h2><p class="filter-note">先读取全部待处理订单及仍负责医院，再明确选全并复核。执行成功后停用原销售账号；已完成结清且无待办的历史单不批量改写。</p><div class="form-grid"><label>原销售 *<select v-model="handoff.fromId" :disabled="writeLocked" @change="handoffChanged()"><option value="">请选择离职销售</option><option v-for="s in sales" :key="s.id" :value="s.id">{{s.name}} · {{s.loginName}}</option></select></label><label>接手销售 *<select v-model="handoff.toId" :disabled="writeLocked" @change="handoffChanged()"><option value="">请选择另一有效销售</option><option v-for="s in sales.filter(s=>s.id!==handoff.fromId)" :key="s.id" :value="s.id">{{s.name}} · {{s.loginName}}</option></select></label><label>交接原因 *<textarea v-model="handoff.reason" maxlength="500" :disabled="writeLocked" @input="handoffChanged(false)"/></label></div><button :disabled="writeLocked" @click="previewHandoff(true)">读取全部待交接范围</button><section v-if="handoff.preview" class="handoff-scope"><h3>{{handoff.preview.from.name}} → {{handoff.preview.to.name}}</h3><div class="handoff-facts"><span>待处理订单 <strong>{{handoff.preview.orderCount}}</strong></span><span>关联应收 <strong>{{handoff.preview.receivableCount}}</strong></span><span>待处理异常 <strong>{{handoff.preview.exceptionCount}}</strong></span><span>仍负责医院 <strong>{{handoff.preview.hospitals.length}}</strong></span></div><p class="muted">应收金额 / 有效已收仅供交接核对；不在此编辑。异常暂停状态、原始负责人及历史操作署名保留。</p><div class="button-row"><button :disabled="writeLocked" @click="selectAllHandoff">明确选全上述订单与医院</button><span>已选订单 {{handoff.orders.length}} · 医院 {{handoff.hospitals.length}}</span></div><div class="table-scroll"><table><thead><tr><th>交接</th><th>订单</th><th>当前状态</th><th>应收 / 有效已收</th><th>异常</th></tr></thead><tbody><tr v-for="o in handoff.preview.orders.slice((handoffOrderPage-1)*25,handoffOrderPage*25)" :key="o.id"><td><input type="checkbox" :checked="handoff.orders.includes(o.id)" :disabled="writeLocked" @change="selectHandoff('orders',o.id,($event.target as HTMLInputElement).checked)" aria-label="选择待交接订单"/></td><td>{{o.orderNo}}</td><td>{{orderStatus(o.status)}}</td><td>{{o.amount??'尚未形成应收'}} / {{o.paid}}</td><td>{{o.pendingException?'待核实，交接后仍暂停':'无待处理异常'}}</td></tr><tr v-if="!handoff.preview.orders.length"><td colspan="5">没有待处理订单。</td></tr></tbody></table></div><div class="pagination"><button :disabled="locked||handoffOrderPage<=1" @click="handoffOrderPage--">订单上一页</button><span>{{handoffOrderPage}} / {{Math.max(1,Math.ceil(handoff.preview.orders.length/25))}}</span><button :disabled="locked||handoffOrderPage*25>=handoff.preview.orders.length" @click="handoffOrderPage++">订单下一页</button></div><h3>仍负责医院的新单归属</h3><div class="hospital-scope"><label v-for="h in handoff.preview.hospitals.slice((handoffHospitalPage-1)*25,handoffHospitalPage*25)" :key="h.id" class="inline-check"><input type="checkbox" :checked="handoff.hospitals.includes(h.id)" :disabled="writeLocked" @change="selectHandoff('hospitals',h.id,($event.target as HTMLInputElement).checked)"/>{{h.name}}{{h.active?'':'（已停用，仍须明确交接）'}}</label><p v-if="!handoff.preview.hospitals.length" class="muted">没有仍负责医院。</p></div><div class="pagination"><button :disabled="locked||handoffHospitalPage<=1" @click="handoffHospitalPage--">医院上一页</button><span>{{handoffHospitalPage}} / {{Math.max(1,Math.ceil(handoff.preview.hospitals.length/25))}}</span><button :disabled="locked||handoffHospitalPage*25>=handoff.preview.hospitals.length" @click="handoffHospitalPage++">医院下一页</button></div><div class="button-row"><button class="primary" :disabled="writeLocked" @click="previewHandoff(false)">按最终选择生成交接预览</button></div><section v-if="handoffReady" class="review-panel"><h3>最终交接确认</h3><p>{{handoff.preview.from.name}} → {{handoff.preview.to.name}} · 订单 {{handoff.orders.length}} 个 · 医院 {{handoff.hospitals.length}} 家</p><p>原因：{{handoff.reason}}</p><p>仅转交当前处理责任并停用原销售；采购明细、报价内容与有效状态、金额、回款、账期、日期及原始历史署名保留。执行时若版本或待办变化，整笔不执行并提示重新预览。预览 15 分钟有效。</p><label class="inline-check"><input v-model="handoffAck" type="checkbox" :disabled="locked||hasPending"/>我已核对双方身份及全部范围，确认交接后停用原销售</label><button class="primary" :disabled="locked||hasPending||!handoffAck||!!storageError" @click="executeHandoff">确认交接并停用原账号</button></section></section></template>
 <SourceBatches v-else-if="tab==='source-batches'" ref="sourcePanel" :api="api" :user-id="userId" :locked="ownLocked||!!storageError" :pending="hasPending" :submit="submit" @busy-changed="childBusy=$event" @failure="report($event)"/>
 <CatalogPanel v-else ref="catalogPanel" :api="api" :user-id="userId" readonly :locked="ownLocked" @busy-changed="childBusy=$event" @failure="report($event)"/>
 <section v-if="review" class="review-panel" aria-label="管理员资料提交复核"><h2>{{review.label}}</h2><dl><div v-for="d in review.details" :key="d.label"><dt>{{d.label}}</dt><dd>{{d.value}}</dd></div></dl><p>{{review.notice}}</p><label class="inline-check"><input v-model="ack" type="checkbox" :disabled="locked||hasPending"/>我已核对本次变更范围与影响</label><div class="button-row"><button class="primary" :disabled="locked||hasPending||!ack||!!storageError" @click="commit">确认提交</button><button :disabled="locked||hasPending" @click="review=null">返回编辑</button></div></section>
 </section>
</template>
<style scoped>
.admin-tabs{display:flex;gap:22px;overflow:auto;border-bottom:1px solid #dce5df;margin:20px 0}.admin-tabs button{border:0;border-radius:0;background:transparent;white-space:nowrap;padding:16px 0;color:#74837a;border-bottom:2px solid transparent}.admin-tabs .selected{color:#215f46;border-bottom-color:#215f46}.admin-actions,.row-actions{display:flex;gap:10px}.master-filter{display:flex;align-items:end;gap:18px;margin:16px 0 24px}.master-filter>label:first-child{width:340px}.master-filter .inline-check{margin-bottom:10px}.account-search{max-width:500px;margin:14px 0 24px}.master-editor{border-top:2px solid #215f46;padding:26px 0;margin:25px 0}.master-editor>form>label{max-width:700px}.review-panel,.credential-panel,.recovery{border-top:2px solid #215f46;padding:24px;background:#f3f7f1;margin:24px 0;line-height:1.8}.recovery{background:#fff7e7;border-color:#c49e57}.credential-panel{background:#fff7e7;border-color:#c49e57}.temporary-credential{display:block;background:#fff;padding:16px;word-break:break-all;user-select:all;font-size:18px;letter-spacing:1px}.review-panel dl{margin:15px 0}.review-panel dl>div{display:grid;grid-template-columns:160px 1fr;gap:20px;border-bottom:1px solid #dae5da;padding:9px 0}.review-panel dt{color:#74837a}.review-panel dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.review-panel>button{margin-top:20px}.unsaved{display:flex;align-items:center;justify-content:space-between;gap:20px;background:#fff9e9;padding:12px 16px;margin:18px 0;font-size:12px}.handoff-scope{border-top:1px solid #dce5df;margin:24px 0;padding-top:22px}.handoff-facts{display:flex;gap:24px;margin:20px 0}.handoff-facts span{color:#74837a}.handoff-facts strong{display:block;font-size:25px;color:#24382f;margin-top:7px}.hospital-scope{display:flex;gap:18px;flex-wrap:wrap;margin:20px 0}.admin-workspace table{min-width:720px}.admin-workspace .error{line-height:1.7}.admin-workspace small button{min-height:24px;font-size:11px;padding:3px 6px}@media(max-width:900px){.master-filter{flex-wrap:wrap}.handoff-facts{flex-wrap:wrap}.admin-tabs{gap:18px}.review-panel dl>div{grid-template-columns:100px 1fr}}
</style>
